CREATE TABLE IF NOT EXISTS departments (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(16) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, alias VARCHAR(120));
CREATE TABLE IF NOT EXISTS semesters (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, start_date DATE, end_date DATE, is_current BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, login_id VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL, full_name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CHECK (role IN ('ADMIN','TEACHER','STUDENT')));
CREATE TABLE IF NOT EXISTS account_password_setup (user_id BIGINT PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS students (user_id BIGINT PRIMARY KEY, student_id VARCHAR(60) NOT NULL UNIQUE, dept_id BIGINT NOT NULL, subject VARCHAR(60), cgpa DECIMAL(4,2), current_semester_id BIGINT, total_credits_completed DECIMAL(6,2) DEFAULT 0, status VARCHAR(20) DEFAULT 'NEW', FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (dept_id) REFERENCES departments(id), FOREIGN KEY (current_semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS teachers (user_id BIGINT PRIMARY KEY, teacher_id VARCHAR(60) NOT NULL UNIQUE, dept_id BIGINT, designation VARCHAR(80), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (dept_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS courses (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(24) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, credit DECIMAL(4,1) NOT NULL, dept_id BIGINT, CHECK (credit > 0), FOREIGN KEY (dept_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS course_prerequisites (course_id BIGINT NOT NULL, prereq_course_id BIGINT NOT NULL, PRIMARY KEY(course_id,prereq_course_id), FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (prereq_course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS rooms (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE, capacity INT NOT NULL);
CREATE TABLE IF NOT EXISTS sections (id BIGINT AUTO_INCREMENT PRIMARY KEY, course_id BIGINT NOT NULL, semester_id BIGINT NOT NULL, section_no VARCHAR(40) NOT NULL, teacher_id BIGINT, room_id BIGINT, capacity INT NOT NULL, seats_taken INT NOT NULL DEFAULT 0, is_offered BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(course_id,semester_id,section_no), CHECK (capacity > 0), CHECK (seats_taken >= 0 AND seats_taken <= capacity), FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (semester_id) REFERENCES semesters(id), FOREIGN KEY (teacher_id) REFERENCES teachers(user_id), FOREIGN KEY (room_id) REFERENCES rooms(id), INDEX ix_section_semester (semester_id,is_offered));
CREATE TABLE IF NOT EXISTS deleted_offerings (section_id BIGINT PRIMARY KEY, original_section_no VARCHAR(40) NOT NULL, deleted_by BIGINT NOT NULL, deleted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (section_id) REFERENCES sections(id), FOREIGN KEY (deleted_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS section_schedules (id BIGINT AUTO_INCREMENT PRIMARY KEY, section_id BIGINT NOT NULL, day VARCHAR(3) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, CHECK (day IN ('SAT','SUN','MON','TUE','WED','THU')), CHECK (start_time < end_time), FOREIGN KEY (section_id) REFERENCES sections(id), INDEX ix_schedule (section_id,day,start_time,end_time));
CREATE TABLE IF NOT EXISTS teacher_course_choices (id BIGINT AUTO_INCREMENT PRIMARY KEY, teacher_id BIGINT NOT NULL, course_id BIGINT NOT NULL, semester_id BIGINT NOT NULL, source VARCHAR(12) NOT NULL, status VARCHAR(16) NOT NULL, confirmed_at TIMESTAMP NULL, assigned_section_id BIGINT, decided_by BIGINT, decided_at TIMESTAMP NULL, UNIQUE(teacher_id,course_id,semester_id), FOREIGN KEY (teacher_id) REFERENCES teachers(user_id), FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (semester_id) REFERENCES semesters(id), FOREIGN KEY (assigned_section_id) REFERENCES sections(id), FOREIGN KEY (decided_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS enrollments (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, section_id BIGINT NOT NULL, semester_id BIGINT NOT NULL, status VARCHAR(16) NOT NULL, confirmed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, dropped_at TIMESTAMP NULL, drop_reason VARCHAR(1000), UNIQUE(student_id,section_id), FOREIGN KEY (student_id) REFERENCES students(user_id), FOREIGN KEY (section_id) REFERENCES sections(id), FOREIGN KEY (semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS advising_windows (id BIGINT AUTO_INCREMENT PRIMARY KEY, semester_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, start_at TIMESTAMP NOT NULL, end_at TIMESTAMP NOT NULL, duration_minutes INT DEFAULT 120, status VARCHAR(16) NOT NULL, created_by BIGINT, CHECK (start_at < end_at), FOREIGN KEY (semester_id) REFERENCES semesters(id), FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS advising_holds (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, section_id BIGINT NOT NULL, window_id BIGINT, source VARCHAR(16) NOT NULL, selected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NOT NULL, status VARCHAR(16) NOT NULL, FOREIGN KEY (student_id) REFERENCES students(user_id), FOREIGN KEY (section_id) REFERENCES sections(id), INDEX ix_holds_expiry (status,expires_at), INDEX ix_holds_student (student_id,section_id,status), FOREIGN KEY (window_id) REFERENCES advising_windows(id));
CREATE TABLE IF NOT EXISTS advising_rules (id BIGINT AUTO_INCREMENT PRIMARY KEY, semester_id BIGINT NOT NULL UNIQUE, min_credit DECIMAL(4,1), max_credit DECIMAL(4,1), drop_deadline DATE, advising_deadline DATE, drop_rules_text VARCHAR(2000), prerequisite_rules_text VARCHAR(2000), probation_cgpa_threshold DECIMAL(3,2), FOREIGN KEY (semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS credit_limit_bands (id BIGINT AUTO_INCREMENT PRIMARY KEY, rule_id BIGINT NOT NULL, min_cgpa DECIMAL(3,2), max_cgpa DECIMAL(3,2), status_label VARCHAR(60), min_credit DECIMAL(4,1), max_credit DECIMAL(4,1), FOREIGN KEY (rule_id) REFERENCES advising_rules(id));
CREATE TABLE IF NOT EXISTS advising_window_sections (window_id BIGINT NOT NULL, section_id BIGINT NOT NULL, PRIMARY KEY(window_id,section_id), FOREIGN KEY (window_id) REFERENCES advising_windows(id), FOREIGN KEY (section_id) REFERENCES sections(id));
CREATE TABLE IF NOT EXISTS notices (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, body VARCHAR(3000) NOT NULL, category VARCHAR(20) NOT NULL, related_window_id BIGINT, published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NULL, FOREIGN KEY (related_window_id) REFERENCES advising_windows(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT, action VARCHAR(80) NOT NULL, entity VARCHAR(60), entity_id BIGINT, detail VARCHAR(2000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (actor_id) REFERENCES users(id), INDEX ix_audit_time (created_at));
CREATE TABLE IF NOT EXISTS prerequisite_records (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, course_id BIGINT NOT NULL, semester_id BIGINT NOT NULL, passed BOOLEAN NOT NULL, recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(user_id), FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (semester_id) REFERENCES semesters(id), INDEX ix_prerequisite_record (student_id,course_id,semester_id));
